    faq_referral_q: "Когда зачисляются реферальные вознаграждения?",
    faq_referral_a: "Вознаграждения за вступление, вознаграждения за активных друзей и реферальные комиссии зачисляются автоматически после проверки требуемой активности. Текущие суммы и ставки смотрите на странице «Друзья».",
    faq_withdraw_q: "Как вывести GEM?",
