    faq_currency_q: "В какой валюте выплачивают?",
    faq_currency_a: "Одобренные выводы выплачиваются в TON на выбранный вами TON-кошелёк. Любая сумма в USD, показанная в приложении, является оценкой; USD не является валютой выплаты.",
