    faq_contest_a: "Конкурс ранжирует соответствующие требованиям завершённые рефералы в период конкурса. Объявленные призы автоматически зачисляются на аккаунты с высшими местами, если они соответствуют требованиям, после окончания конкурса.",
    faq_language_q: "Как сменить язык приложения?",
    faq_language_a: "Откройте Аккаунт, нажмите «Сменить язык» и выберите язык из списка.",
    faq_accounts_q: "Можно ли использовать несколько аккаунтов?",
    faq_accounts_a: "Разрешён только один аккаунт на человека. Несколько аккаунтов или автоматизированная активность могут быть ограничены, а связанные вознаграждения — отменены.",
    faq_proof_q: "Где найти подтверждение платежа?",
