    legal_last_updated: "Последнее обновление: 2 октября 2026",
    legal_terms_intro: "Добро пожаловать в Paid Adz. Используя приложение, вы соглашаетесь с настоящими Условиями. Если вы не согласны — прекратите использование приложения.",
