    legal_terms_rewards_title: "GEM и реферальные вознаграждения",
    legal_terms_gem: "GEM — единица вознаграждения в приложении. Вознаграждения зависят от соответствующей требованиям активности и проверки. Любой эквивалент в USD, показанный в приложении, является оценкой, может изменяться и не является выплатой в USD.",
    legal_terms_referrals: "Реферальные вознаграждения и комиссии зачисляются автоматически после подтверждения выполнения требуемых условий. Текущие суммы и ставки указаны на странице «Друзья». Призы по конкурсам выплачиваются в соответствии с опубликованными правилами конкурса.",
    legal_terms_withdrawals_title: "Вывод в TON",
    legal_terms_withdrawals: "Право на выплату имеют соответствующие требованиям GEM — их можно запросить для выплаты в TON на выбранный TON-кошелёк. На экране вывода указаны текущие минимум и комиссия. Запросы проходят проверку; отправка запроса не гарантирует его одобрение или выплату.",
    legal_terms_fair_use_title: "Честное использование и меры",
    legal_terms_fair_use: "Используйте один аккаунт на человека. Мы можем ограничить аккаунты или отменить вознаграждения, связанные с мошенничеством, манипуляциями, злоупотреблениями или нарушением этих Условий.",
    legal_terms_changes_title: "Изменения",
    legal_terms_changes: "Функции приложения, настройки вознаграждений и настоящие Условия могут меняться. Применяется последняя версия, отображённая в приложении.",
    legal_privacy_intro: "В этом уведомлении объясняется, какие данные Paid Adz использует для предоставления и защиты приложения.",
    legal_privacy_data_title: "Данные, которые мы используем",
