    legal_privacy_wallet_title: "TON-кошелёк",
    legal_privacy_wallet: "Если вы подключаете или сохраняете TON-кошелёк, мы используем его публичный адрес для запросов на вывод и управления выплатами. Никогда не делитесь фразой восстановления или приватным ключом кошелька.",
    legal_privacy_services_title: "Сторонние сервисы",
    legal_privacy_services: "Telegram, TON Connect, рекламные сети и поставщики заданий, а также другие интегрированные сервисы могут обрабатывать данные при использовании их функций в соответствии со своими уведомлениями о конфиденциальности.",
    legal_privacy_retention_title: "Хранение данных",
