    faq_currency_a: "برداشت‌های تأییدشده به‌صورت TON به کیف پول TON انتخاب‌شده شما پرداخت می‌شوند. هر مبلغی که به‌صورت USD نمایش داده می‌شود تخمینی است؛ USD ارز پرداخت نیست.",
    faq_contest_q: "جوایز مسابقه معرفی چه زمانی منظور می‌شوند؟",
    faq_contest_a: "مسابقه در دورهٔ مسابقه، ارجاعات تکمیل‌شدهٔ واجد شرایط را رتبه‌بندی می‌کند. جوایز منتشرشده پس از پایان مسابقه به‌صورت خودکار به حساب‌های واجد شرایط با رتبهٔ بالا منظور می‌شوند.",
    faq_language_q: "چطور زبان برنامه را تغییر دهم؟",
    faq_language_a: "Account را باز کنید، روی Change language بزنید و از فهرست زبان‌ها انتخاب کنید.",
    faq_accounts_q: "می‌توانم از چند حساب استفاده کنم؟",
    faq_accounts_a: "برای هر فرد تنها یک حساب مجاز است. حساب‌های متعدد یا فعالیت‌های خودکار ممکن است محدود شوند و جوایز مرتبط بازگردانده شوند.",
    faq_proof_q: "کجا می‌توانم مدرک پرداخت را پیدا کنم؟",
    faq_proof_a: "Account را باز کنید و روی Proof of Payment بزنید. در صورت موجود بودن، لینک صفحهٔ اثبات پرداخت پیکربندی‌شده برای برنامه را باز می‌کند.",
    legal_last_updated: "آخرین به‌روزرسانی: 2 اکتبر 2026",
    legal_terms_intro: "به Paid Adz خوش آمدید. با استفاده از برنامه، شما با این شرایط موافقت می‌کنید. اگر موافق نیستید، از استفاده از برنامه خودداری کنید.",
    legal_terms_eligibility_title: "صلاحیت و حساب",
    legal_terms_eligibility: "فقط در مناطقی از برنامه استفاده کنید که از نظر قانونی مجاز هستید. حساب Telegram خود را امن نگه دارید؛ شما مسئول فعالیت‌های انجام‌شده از طریق حساب خود هستید.",
    legal_terms_rewards_title: "GEM و جوایز معرفی",
    legal_terms_gem: "GEM یک واحد پاداش داخل برنامه است. دریافت جوایز بستگی به فعالیت‌های واجد شرایط و تأیید آن‌ها دارد. هر معادل USD که در برنامه نشان داده می‌شود تخمینی است، ممکن است تغییر کند و به‌عنوان پرداخت به‌صورت USD انجام نمی‌شود.",
    legal_terms_referrals: "جوایز و کمیسیون‌های معرفی پس از تأیید شرایط لازم به‌صورت خودکار منظور می‌شوند. مقادیر و نرخ‌های فعلی در صفحه دوستان نمایش داده می‌شوند. جوایز مسابقه طبق قوانین منتشرشدهٔ مسابقه اعمال می‌شوند.",
    legal_terms_withdrawals_title: "برداشت‌های TON",
    legal_terms_withdrawals: "می‌توانید درخواست پرداخت GEM‌های واجد شرایط را به‌صورت TON به کیف پول TON انتخاب‌شده ارسال کنید. صفحهٔ برداشت حداقل مبلغ و کارمزد جاری را نشان می‌دهد. درخواست‌ها بررسی می‌شوند؛ ارسال درخواست تضمینی برای تأیید یا پرداخت نیست.",
    legal_terms_fair_use_title: "استفاده عادلانه و اجرا",
    legal_terms_fair_use: "برای هر فرد تنها یک حساب مجاز است. ما ممکن است حساب‌ها را محدود یا جوایز مرتبط با تقلب، دستکاری، سوء‌استفاده یا نقض این شرایط را بازگردانیم.",
    legal_terms_changes_title: "تغییرات",
    legal_terms_changes: "ویژگی‌های برنامه، تنظیمات پاداش و این شرایط ممکن است تغییر کنند. آخرین نسخهٔ نمایش‌داده‌شده در برنامه اعمال می‌شود.",
    legal_privacy_intro: "این اطلاعیه اطلاعاتی را توضیح می‌دهد که Paid Adz برای ارائه و حفاظت از برنامه استفاده می‌کند.",
    legal_privacy_data_title: "اطلاعات مورد استفاده",
    legal_privacy_data: "ما شناسه Telegram و جزئیات پروفایل شما، فعالیت‌های داخل برنامه، رخدادهای مربوط به وظایف و تبلیغات، سوابق ارجاع، موجودی جوایز و اطلاعات تراکنش لازم برای راه‌اندازی سرویس را پردازش می‌کنیم.",
    legal_privacy_wallet_title: "کیف پول TON",
    legal_privacy_wallet: "اگر کیف پول TON را متصل یا ذخیره کنید، ما از آدرس عمومی آن برای درخواست‌های برداشت و مدیریت پرداخت‌ها استفاده می‌کنیم. هرگز عبارت بازیابی یا کلید خصوصی کیف پول خود را به اشتراک نگذارید.",
    legal_privacy_services_title: "خدمات شخص ثالث",
    legal_privacy_services: "Telegram، TON Connect، ارائه‌دهندگان تبلیغات و وظایف، و سایر سرویس‌های یکپارچه ممکن است هنگام استفاده از امکانات آن‌ها اطلاعات را مطابق اطلاعیه‌های حریم خصوصی خود پردازش کنند.",
    legal_privacy_retention_title: "ذخیره‌سازی و نگهداری",
    legal_privacy_retention: "ما اطلاعات را به میزانی که برای راه‌اندازی و محافظت از برنامه، مدیریت جوایز و برداشت‌ها، و رسیدگی به مشکلات حساب یا تکالیف قابل اجرا لازم است نگه می‌داریم.",
    legal_privacy_contact_title: "درخواست‌های حریم خصوصی",
    legal_privacy_contact: "برای سوالات حریم خصوصی یا درخواست‌های مربوط به داده‌های حساب، از طریق لینک موجود در برنامه با تیم پشتیبانی تماس بگیرید و UID تلگرام خود را وارد کنید.",
    legal_acceptable_intro: "از Paid Adz به‌صورت صادقانه و فقط از طریق امکانات موردنظر برنامه استفاده کنید.",
    legal_acceptable_rules_title: "فعالیت‌های ممنوعه",
    legal_acceptable_prohibited: "ایجاد چند حساب، خودکارسازی تبلیغات یا وظایف، جعل ارجاعات، دستکاری مسابقات یا جوایز، سوءاستفاده از باگ‌ها، مختل‌سازی سرویس یا ارسال اطلاعات نادرست ممنوع است.",
    legal_acceptable_enforcement_title: "اجرای قوانین",
    legal_acceptable_enforcement: "شک به سوء‌استفاده ممکن است منجر به بررسی، بازگرداندن جوایز، محدودیت در برداشت‌ها یا تعلیق حساب طبق قوانین برنامه شود.",
