    legal_terms_intro: "Bienvenue sur Paid Adz. En utilisant l'application, vous acceptez ces Conditions. Si vous n'acceptez pas, cessez d'utiliser l'application.",
    legal_terms_eligibility_title: "Éligibilité et compte",
    legal_terms_eligibility: "Utilisez l'application uniquement là où vous y êtes légalement autorisé. Protégez votre compte Telegram ; vous êtes responsable des activités effectuées via votre compte.",
    legal_terms_rewards_title: "GEM et récompenses de parrainage",
    legal_terms_gem: "GEM est une unité de récompense dans l'application. Les récompenses dépendent d'activités éligibles et de leur vérification. Tout équivalent en USD affiché dans l'application est une estimation, peut varier et n'est pas un paiement en USD.",
    legal_terms_referrals: "Les récompenses et commissions de parrainage sont créditées automatiquement une fois les conditions requises vérifiées. Les montants et taux actuels figurent sur la page Amis. Les récompenses de concours suivent les règles publiées du concours.",
    legal_terms_withdrawals_title: "Retraits en TON",
    legal_terms_withdrawals: "Les GEM éligibles peuvent être demandés pour paiement en TON vers un portefeuille TON sélectionné. L'écran de retrait indique le minimum et les frais actuels. Les demandes sont examinées ; l'envoi d'une demande n'assure pas l'approbation ni le paiement.",
    legal_terms_fair_use_title: "Utilisation équitable et application",
    legal_terms_fair_use: "Utilisez un seul compte par personne. Nous pouvons restreindre des comptes ou annuler des récompenses associées à la fraude, à la manipulation, aux abus ou à une violation de ces Conditions.",
    legal_terms_changes_title: "Modifications",
    legal_terms_changes: "Les fonctionnalités de l'application, les paramètres de récompense et ces Conditions peuvent changer. La dernière version affichée dans l'application s'applique.",
    legal_privacy_intro: "Cette notice explique les informations qu'Paid Adz utilise pour fournir et protéger l'application.",
    legal_privacy_data_title: "Informations que nous utilisons",
    legal_privacy_data: "Nous traitons votre identifiant Telegram et les informations de profil, l'activité dans l'application, les événements de tâches et publicités, les enregistrements de parrainage, les soldes de récompense et les informations de transaction nécessaires au fonctionnement du service.",
    legal_privacy_wallet_title: "Portefeuille TON",
    legal_privacy_wallet: "Si vous connectez ou enregistrez un portefeuille TON, nous utilisons son adresse publique pour les demandes de retrait et la gestion des paiements. Ne partagez jamais votre phrase de récupération ni votre clé privée.",
    legal_privacy_services_title: "Services tiers",
    legal_privacy_services: "Telegram, TON Connect, les fournisseurs de publicité et de tâches, et d'autres services intégrés peuvent traiter des informations lorsque vous utilisez leurs fonctionnalités, selon leurs propres avis de confidentialité.",
    legal_privacy_retention_title: "Stockage et conservation",
    legal_privacy_retention: "Nous conservons les informations selon les besoins pour exploiter et protéger l'application, gérer les récompenses et les retraits, et traiter les problèmes de compte ou obligations applicables.",
    legal_privacy_contact_title: "Demandes de confidentialité",
    legal_privacy_contact: "Pour toute question sur la confidentialité ou une demande concernant les données de compte, contactez l'équipe support via le lien fourni dans l'application et incluez votre UID Telegram.",
    legal_acceptable_intro: "Utilisez Paid Adz honnêtement et uniquement via les fonctions prévues de l'application.",
    legal_acceptable_rules_title: "Activités interdites",
