    faq_status_q: "আমি কীভাবে একটি উত্তোলনের অবস্থা যাচাই করব?",
    faq_status_a: "Account খুলুন → Transactions খুলে আপনার অনুরোধের অবস্থা দেখুন। TON পেমেন্ট পাঠানোর আগে অনুরোধগুলো পর্যালোচনা করা হয়।",
    faq_currency_q: "পেমেন্ট কোন মুদ্রায় করা হয়?",
    faq_currency_a: "অনুমোদিত উত্তোলনগুলি আপনার নির্বাচিত TON ওয়ালেটে TON হিসেবে প্রদান করা হয়। অ্যাপে দেখানো USD কোনো কালে পেআউট মুদ্রা নয়; তা একটি আনুমানিক মান মাত্র।",
    faq_contest_q: "রেফারেল প্রতিযোগিতার পুরস্কার কখন ক্রেডিট করা হয়?",
    faq_contest_a: "প্রতিযোগিতা চলাকালে যোগ্যভাবে সম্পন্ন রেফারেলগুলিকে র‌্যাঙ্ক করা হয়। প্রকাশিত পুরস্কারগুলো প্রতিযোগিতা শেষ হওয়ার পর শীর্ষস্থায় থাকা যোগ্য অ্যাকাউন্টগুলোতে স্বয়ংক্রিয়ভাবে ক্রেডিট করা হয়।",
    faq_language_q: "আমি কীভাবে অ্যাপের ভাষা পরিবর্তন করব?",
    faq_language_a: "Account খুলুন, Change language ট্যাপ করুন, এবং ভাষার তালিকা থেকে নির্বাচন করুন।",
    faq_accounts_q: "আমি কি একাধিক অ্যাকাউন্ট ব্যবহার করতে পারি?",
    faq_accounts_a: "প্রতি ব্যক্তির জন্য শুধুমাত্র একটি অ্যাকাউন্ট অনুমোদিত। একাধিক অ্যাকাউন্ট বা স্বয়ংক্রিয় কার্যকলাপ সীমাবদ্ধ করা হতে পারে এবং সংশ্লিষ্ট পুরস্কার প্রত্যাহার করা যেতে পারে।",
    faq_proof_q: "পেমেন্টের প্রমাণ কোথায় দেখতে পাব?",
    faq_proof_a: "Account খুলুন এবং Proof of Payment ট্যাপ করুন। উপলব্ধ থাকলে লিঙ্কটি অ্যাপের জন্য কনফিগার করা পেমেন্ট-প্রমাণ পেজ খুলবে।",
    legal_last_updated: "শেষ আপডেট: 2 অক্টোবর 2026",
    legal_terms_intro: "Paid Adz-এ স্বাগতম। অ্যাপ ব্যবহার করে আপনি এই শর্তাবলীতে সম্মত হচ্ছেন। যদি সম্মত না হন, তাহলে অ্যাপ ব্যবহার বন্ধ করুন।",
    legal_terms_eligibility_title: "যোগ্যতা ও অ্যাকাউন্ট",
    legal_terms_eligibility: "অ্যাপটি শুধুমাত্র যেখানে আপনি আইনগতভাবে ব্যবহার করার অনুমতি পাচ্ছেন সেখানে ব্যবহার করুন। আপনার Telegram অ্যাকাউন্ট নিরাপদ রাখুন; আপনার অ্যাকাউন্টের মাধ্যমে পরিচালিত কার্যকলাপের জন্য আপনি দায়ী।",
    legal_terms_rewards_title: "GEM ও রেফারেল পুরস্কার",
    legal_terms_gem: "GEM হচ্ছে অ্যাপে ব্যবহৃত একটি রিওয়ার্ড ইউনিট। পুরস্কার যোগ্য কার্যকলাপ ও যাচাইয়ের উপর নির্ভর করে। অ্যাপে দেখানো যেকোনো USD সমতুল্য একটি আনুমানিক সংখ্যা, পরিবর্তনশীল এবং USD পেআউট নয়।",
    legal_terms_referrals: "রেফারেল পুরস্কার ও কমিশন প্রয়োজনীয় শর্ত যাচাই হলে স্বয়ংক্রিয়ভাবে ক্রেডিট করা হয়। বর্তমান পরিমাণ ও হার Friends page-এ দেখানো থাকে। প্রতিযোগিতার পুরস্কার প্রকাশিত নিয়ম অনুসারে প্রদান করা হবে।",
    legal_terms_withdrawals_title: "TON উত্তোলন",
    legal_terms_withdrawals: "যোগ্য GEM নির্বাচিত TON ওয়ালেটে TON হিসেবে পেআউটের জন্য অনুরোধ করা যেতে পারে। উত্তোলন স্ক্রীনে বর্তমান ন্যূনতম এবং ফি দেখানো হয়। অনুরোধগুলো পর্যালোচনা করা হয়; অনুরোধ জমা দেওয়া মানেই অনুমোদন বা পেমেন্টের নিশ্চয়তা নয়।",
    legal_terms_fair_use_title: "ন্যায়সঙ্গত ব্যবহার ও কার্যকরীকরণ",
